mapper.insert:
INSERT INTO bgxt_jyjg (brxx_id, xmdm, xmzwmc, jyjg, jldw, ckz, ckzgx, ckzdx, bjzgx, bjzdx, gdbj)
SELECT #{brxxId}, COALESCE(jf.xmdm, CAST(#{xmid} AS CHAR)), COALESCE(jf.xmzwmc, ''), #{jyjg}, COALESCE(jf.xmdw, ''), #{ckz}, #{ckzgx}, #{ckzdx}, #{bjzgx}, #{bjzdx}, #{gdbj}
FROM sys_jyxm_full jf WHERE jf.xmid = #{xmid} LIMIT 1

mapper.update:
UPDATE bgxt_jyjg jg
JOIN (SELECT xmid, MAX(xmdm) AS xmdm, MAX(xmzwmc) AS xmzwmc, MAX(xmdw) AS xmdw FROM sys_jyxm_full WHERE xmid = #{xmid} GROUP BY xmid) jf ON jg.xmdm = jf.xmdm
SET jg.jyjg=#{jyjg}, jg.xmzwmc=COALESCE(jf.xmzwmc, jg.xmzwmc), jg.jldw=COALESCE(jf.xmdw, jg.jldw),
    jg.ckz=#{ckz}, jg.ckzgx=#{ckzgx}, jg.ckzdx=#{ckzdx}, jg.bjzgx=#{bjzgx}, jg.bjzdx=#{bjzdx}, jg.gdbj=#{gdbj},
    jg.cjmxid=#{cjmxid}
WHERE jg.brxx_id=#{brxxId}

mapper.select:
SELECT COUNT(*) FROM bgxt_jyjg jg
JOIN (SELECT MAX(xmdm) AS xmdm FROM sys_jyxm_full WHERE xmid = #{xmid} GROUP BY xmid) jf ON jg.xmdm = jf.xmdm
WHERE jg.brxx_id = #{brxxId}
